+
+  struct PackedNode {
+    uint32_t xy;
+    int16_t z;
+    uint16_t b;
+  };
+  static_assert(sizeof(PackedNode) == 8);
+
+  static __attribute__((always_inline)) int16_t pack_component(float value) {
+    int rounded = static_cast<int>(value * 32767.0f +
+                                   __builtin_copysignf(0.5f, value));
+    return static_cast<int16_t>(hs::clamp(rounded, -32767, 32767));
+  }
+
+  static __attribute__((always_inline)) PackedNode
+  pack_node(const math::Vector &point, uint16_t b) {
+    uint16_t x = static_cast<uint16_t>(pack_component(point.x));
+    uint16_t y = static_cast<uint16_t>(pack_component(point.y));
+    return {static_cast<uint32_t>(x) | (static_cast<uint32_t>(y) << 16),
+            pack_component(point.z), b};
+  }
+
+  static __attribute__((always_inline)) uint32_t
+  packed_dist2(const PackedNode &query, const PackedNode &node) {
+#if defined(__arm__)
+    uint32_t xy = __builtin_arm_qsub16(query.xy, node.xy);
+    uint32_t z = __builtin_arm_qsub16(static_cast<uint16_t>(query.z),
+                                     static_cast<uint16_t>(node.z));
+    // Saturated lanes exceed kernel support; three halfword squares fit uint32.
+    return static_cast<uint32_t>(__builtin_arm_smuad(xy, xy)) +
+           static_cast<uint32_t>(__builtin_arm_smuad(z, z));
+#else
+    int dx = hs::clamp(static_cast<int>(static_cast<int16_t>(query.xy)) -
+                          static_cast<int16_t>(node.xy), -32768, 32767);
+    int dy = hs::clamp(static_cast<int>(static_cast<int16_t>(query.xy >> 16)) -
+                          static_cast<int16_t>(node.xy >> 16), -32768, 32767);
+    int dz = hs::clamp(static_cast<int>(query.z) - node.z, -32768, 32767);
+    return static_cast<uint32_t>(dx * dx) + static_cast<uint32_t>(dy * dy) +
+           static_cast<uint32_t>(dz * dz);
+#endif
+  }
